// 1. Normalize intake fields from Cal.com webhook
const rawBody = $input.first().json.body || $input.first().json;
const booking = rawBody.payload || rawBody.data || rawBody;
const attendee = booking.attendees?.[0] || {};

const rawPhone = attendee.phoneNumber || attendee.phone || booking.responses?.phone?.value || booking.responses?.phone || '';
let phone = rawPhone.replace(/[^\d+]/g, '');
if (phone.length === 10 && !phone.startsWith('+')) {
  phone = `+91${phone}`;
}

const email = (attendee.email || booking.responses?.email?.value || booking.responses?.email || '').toLowerCase().trim();
const name = attendee.name || booking.responses?.name?.value || booking.responses?.name || 'Discovery Client';
const startTime = booking.startTime || booking.start_time || new Date().toISOString();
const timezone = attendee.timeZone || booking.timezone || 'Asia/Kolkata';
const meetingLink = booking.videoCallData?.url || booking.location || booking.meetingUrl || '';
const bookingUid = String(booking.uid || booking.bookingId || booking.id || `bk-${Date.now()}`);
const notes = booking.responses?.problem?.value || booking.responses?.problem || booking.description || 'Discovery Call Intake';

return [{
  json: {
    booking_uid: bookingUid,
    name,
    email,
    phone,
    meeting_time: startTime,
    timezone,
    meeting_link: meetingLink,
    notes
  }
}];

